insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Outpost', 'monument-outpost', 'monument', 'Xavfsiz hudud', 'Savdo avtomatlari, qayta ishlash, ish stollari va xavfsiz savdo imkoniyatlari mavjud bo‘lgan hudud.', '{"name":"Outpost","type":"Xavfsiz hudud","size":"Safe zone","desc":"Savdo avtomatlari, qayta ishlash, ish stollari va xavfsiz savdo imkoniyatlari mavjud bo‘lgan hudud.","tips":["Hudud ichida qurol ishlatmang va boshqa o‘yinchilarga zarar yetkazmang.","Savdo avtomatlari va qayta ishlash uskunalaridan foydalaning."],"loot":"Asosiy foyda: savdo, qayta ishlash va xizmatlar.","color":"green"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Bandit Camp', 'monument-bandit-camp', 'monument', 'Xavfsiz hudud', 'NPC savdogarlari va qimor o‘yinlari joylashgan xavfsiz savdo hududi.', '{"name":"Bandit Camp","type":"Xavfsiz hudud","size":"Safe zone","desc":"NPC savdogarlari va qimor o‘yinlari joylashgan xavfsiz savdo hududi.","tips":["Savdo va resurs almashinuvi uchun boring.","Hudud qoidalariga rioya qiling."],"loot":"Asosiy foyda: savdo va maxsus xizmatlar.","color":"green"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Fishing Village', 'monument-fishing-village', 'monument', 'Xavfsiz hudud', 'Baliq ovlash va dengiz transportiga oid xizmatlar mavjud qirg‘oq hududi.', '{"name":"Fishing Village","type":"Xavfsiz hudud","size":"Safe zone","desc":"Baliq ovlash va dengiz transportiga oid xizmatlar mavjud qirg‘oq hududi.","tips":["Qayiq va baliq ovlash bilan bog‘liq xizmatlarni tekshiring.","Suv bo‘ylab harakatlanish uchun qulay nuqta."],"loot":"Asosiy foyda: dengiz xizmatlari va savdo.","color":"green"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Abandoned Supermarket', 'monument-abandoned-supermarket', 'monument', 'Kichik monument', 'Oziq-ovqat va kundalik buyumlar qidirish mumkin bo‘lgan kichik monument.', '{"name":"Abandoned Supermarket","type":"Kichik monument","size":"Small","desc":"Oziq-ovqat va kundalik buyumlar qidirish mumkin bo‘lgan kichik monument.","tips":["Atrofdagi yo‘llarni tekshiring.","Boshqa o‘yinchilar kelishi mumkin — ehtiyot bo‘ling."],"loot":"Odatda oddiy loot konteynerlari va barrel/bochkalarga e’tibor bering.","color":"blue","image_url":"https://www.gamingonlinux.com/uploads/articles/article_media/14176706571504812791gol1.jpg"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Lighthouse', 'monument-lighthouse', 'monument', 'Kichik monument', 'Sohil bo‘yida joylashadigan mayoq. Yangi boshlovchilar uchun loot qidirish nuqtasi.', '{"name":"Lighthouse","type":"Kichik monument","size":"Small","desc":"Sohil bo‘yida joylashadigan mayoq. Yangi boshlovchilar uchun loot qidirish nuqtasi.","tips":["Mayoqning yuqori qismlarini ham tekshiring.","Sohil bo‘ylab barrel va konteynerlarni qidiring."],"loot":"Oddiy loot va qayta ishlashga yaroqli komponentlar.","color":"blue","image_url":"https://cdn.vartolo.net/Pages/Rust-Monument/images/Lighthouse.jpg"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Mining Outpost', 'monument-mining-outpost', 'monument', 'Kichik monument', 'Konchilik mavzusidagi kichik hudud. Yo‘l bo‘yidagi resurs va konteynerlarni qidirish mumkin.', '{"name":"Mining Outpost","type":"Kichik monument","size":"Small","desc":"Konchilik mavzusidagi kichik hudud. Yo‘l bo‘yidagi resurs va konteynerlarni qidirish mumkin.","tips":["Hudud atrofidagi barrel va qutilarni tekshiring.","Yaqin atrofdagi yo‘llarni ham aylaning."],"loot":"Oddiy loot konteynerlari va komponentlar.","color":"blue"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Oxum’s Gas Station', 'monument-oxums-gas-station', 'monument', 'Kichik monument', 'Yoqilg‘i shoxobchasi ko‘rinishidagi monument. Loot va qayta ishlash uchun foydali bo‘lishi mumkin.', '{"name":"Oxum’s Gas Station","type":"Kichik monument","size":"Small","desc":"Yoqilg‘i shoxobchasi ko‘rinishidagi monument. Loot va qayta ishlash uchun foydali bo‘lishi mumkin.","tips":["Binoning ichki qismlari va tomini tekshiring.","Recycler mavjudligini serverdagi joriy holat bo‘yicha tekshiring."],"loot":"Konteynerlar, barrel va komponentlar.","color":"blue","image_url":"https://static.wixstatic.com/media/e2b728_24be5129a1574ba8879cbd2b38b28cbe~mv2.png/v1/fill/w_1000%2Ch_667%2Cal_c%2Cq_90%2Cusm_0.66_1.00_0.01/e2b728_24be5129a1574ba8879cbd2b38b28cbe~mv2.png"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Abandoned Cabins', 'monument-abandoned-cabins', 'monument', 'Kichik monument', 'O‘rmon hududida uchraydigan tashlandiq kulbalar majmuasi.', '{"name":"Abandoned Cabins","type":"Kichik monument","size":"Small","desc":"O‘rmon hududida uchraydigan tashlandiq kulbalar majmuasi.","tips":["Kulbalar orasini va tashqi hududni tekshiring.","Atrofdagi xavflarga e’tibor bering."],"loot":"Oddiy konteynerlar va resurslar.","color":"blue"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Airfield', 'monument-airfield', 'monument', 'Katta monument', 'Keng aerodrom hududi. Bir nechta bino, angar va yerosti yo‘laklari mavjud.', '{"name":"Airfield","type":"Katta monument","size":"Large","desc":"Keng aerodrom hududi. Bir nechta bino, angar va yerosti yo‘laklari mavjud.","tips":["Hudud katta — kirishdan oldin chiqish yo‘lini rejalashtiring.","Radiatsiya va boshqa o‘yinchilarga tayyor bo‘ling.","Puzzle mavjud bo‘lgan eshiklar uchun kerakli kartalarni olib boring."],"loot":"Yuqori darajadagi konteynerlar va harbiy loot imkoniyati.","color":"orange","image_url":"https://static.wikia.nocookie.net/play-rust/images/7/70/Airfield_main_view.jpg/revision/latest/scale-to-width-down/1200?cb=20161122165909","stats":{"tier":"Tier 2","crates":"29","barrels":"11","scientists":"3","recyclers":"2","radiation":"11"},"source_url":"https://rusthelp.com/monument/airfield","puzzle":{"cards":"Green + Blue","fuses":"2 × Electric Fuse","route":["Ikki elektr switchini faollashtiring.","Asosiy puzzle binosiga o‘ting va fuse box’ga 1 ta fuse joylang.","Timer switchni yoqing, Green Keycard bilan ixtiyoriy xonani tekshiring.","Yuqori qavatda Blue Keycard’ni swipe qiling va lootni oling."],"reward":"Red Keycard, harbiy loot va blueprint fragmentlar","note":"Ikkinchi fuse alohida elektr zanjiri/puzzle bosqichiga kerak bo‘lishi mumkin; serverdagi joriy holatni tekshiring."}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Train Yard', 'monument-train-yard', 'monument', 'Katta monument', 'Temiryo‘l infratuzilmasi, vagonlar va sanoat binolaridan iborat monument.', '{"name":"Train Yard","type":"Katta monument","size":"Large","desc":"Temiryo‘l infratuzilmasi, vagonlar va sanoat binolaridan iborat monument.","tips":["Baland nuqtalar va vagonlarni tekshiring.","Puzzle xonasi uchun kerakli kartalarni tayyorlang.","Hudud ochiq bo‘lgani uchun snayperlardan ehtiyot bo‘ling."],"loot":"Harbiy va sanoat loot konteynerlari.","color":"orange","image_url":"https://eip.gg/wp-content/uploads/2022/08/New-Train.jpg","stats":{"tier":"Tier 2","crates":"30","barrels":"15","scientists":"4","recyclers":"1","radiation":"11 (max 26)"},"source_url":"https://rusthelp.com/monument/train-yard","puzzle":{"cards":"Blue (Green — ixtiyoriy xona uchun)","fuses":"1 × Electric Fuse","route":["Asosiy puzzle binosiga qarama-qarshi binodagi switchni yoqing.","Minoradagi yuqori qavat switchini faollashtiring.","Puzzle binosiga kiring va orqa tomondagi fuse box’ga fuse qo‘ying.","Timer switchni yoqing, yuqoriga ko‘tarilib Blue Keycard’ni swipe qiling."],"reward":"Red Keycard va Military Crates"}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Water Treatment Plant', 'monument-water-treatment-plant', 'monument', 'Katta monument', 'Suv tozalash inshootlari va quvurlardan iborat yirik sanoat hududi.', '{"name":"Water Treatment Plant","type":"Katta monument","size":"Large","desc":"Suv tozalash inshootlari va quvurlardan iborat yirik sanoat hududi.","tips":["Binolar ichini va quvur yo‘laklarini tekshiring.","Puzzle yo‘nalishini oldindan o‘rganing.","Radiatsiya himoyasini unutmang."],"loot":"Sanoat va harbiy loot konteynerlari.","color":"orange","image_url":"https://staticg.sportskeeda.com/editor/2025/10/cd883-17597191979351-1920.jpg","stats":{"tier":"Tier 2","crates":"34","barrels":"13","scientists":"0","recyclers":"1","radiation":"0 (max 26)"},"source_url":"https://rusthelp.com/monument/water-treatment-plant","puzzle":{"cards":"Blue","fuses":"1 × Electric Fuse","route":["Monument ichidagi fuse box’ni toping.","Electric Fuse joylang va yaqin switchni yoqing.","Timer tugashidan oldin Blue Keycard’ni reader’da swipe qiling.","Loot xonasini tekshirib, xavfsiz chiqish yo‘lidan qayting."],"reward":"Red Keycard va Military Crates"}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Power Plant', 'monument-power-plant', 'monument', 'Katta monument', 'Elektr stansiyasi va texnik inshootlardan iborat murakkab monument.', '{"name":"Power Plant","type":"Katta monument","size":"Large","desc":"Elektr stansiyasi va texnik inshootlardan iborat murakkab monument.","tips":["Inshootlar orasidagi yo‘laklarni o‘rganing.","Puzzle uchun kerakli kartalarni olib boring.","Hududni to‘liq aylanib chiqishga vaqt ajrating."],"loot":"Sanoat va harbiy konteynerlar.","color":"orange","image_url":"https://staticg.sportskeeda.com/editor/2024/09/ae0c5-17261211910451-1920.jpg","stats":{"tier":"Tier 3","crates":"31","barrels":"15","scientists":"0","recyclers":"3 green + 1 red","radiation":"0 (max 52)"},"source_url":"https://rusthelp.com/monument/power-plant","puzzle":{"cards":"Green + Blue","fuses":"1 × Electric Fuse","route":["Green va Blue Keycard hamda Electric Fuse olib boring.","Puzzle binosidagi elektr zanjirini yoqing.","Kerakli switchlarni ketma-ket faollashtirib timerga yetib boring.","Blue Keycard bilan loot xonasini oching."],"reward":"Red Keycard va yuqori darajadagi loot","note":"Power Plant’da Heavy Fuse bilan bog‘liq alohida elektr tarmog‘i ham bor; bu oddiy Electric Fuse puzzle’dan farq qiladi."}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Launch Site', 'monument-launch-site', 'monument', 'Katta monument', 'Raketa uchirish majmuasi. Keng, xavfli va yuqori darajadagi loot imkoniyatlariga ega.', '{"name":"Launch Site","type":"Katta monument","size":"Large","desc":"Raketa uchirish majmuasi. Keng, xavfli va yuqori darajadagi loot imkoniyatlariga ega.","tips":["Yuqori radiatsiya xavfiga tayyorlaning.","Himoya kiyimi va davolovchi vositalar olib boring.","Bradley APC xavfini hisobga oling."],"loot":"Yuqori darajadagi harbiy loot. Bradley APC mavjud.","color":"red","image_url":"https://cdn-ak.f.st-hatena.com/images/fotolife/g/game-lab/20240410/20240410004239.jpg","stats":{"tier":"Tier 3","crates":"85","barrels":"64","scientists":"8","recyclers":"1","radiation":"11 (max 52)"},"source_url":"https://rusthelp.com/monument/launch-site","puzzle":{"cards":"Green + Red","fuses":"2 × Electric Fuse","route":["Radiatsiyaga qarshi kiyim, Green va Red Keycard olib boring.","Puzzle uchun belgilangan ikki fuse box’ga fuse joylang.","Kerakli switchlarni faollashtirib timer oynasida eshikka yetib boring.","Red Keycard bilan yuqori darajadagi loot xonasini oching."],"reward":"Elite loot va yuqori darajadagi harbiy konteynerlar","note":"Launch Site’dagi elektr grid va loot room talablari yangilanishlarga qarab o‘zgarishi mumkin."}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Military Tunnels', 'monument-military-tunnels', 'monument', 'Katta monument', 'Yerosti harbiy tunnel tizimi. Kuchli NPC himoyasi sababli yaxshi tayyorgarlik talab qiladi.', '{"name":"Military Tunnels","type":"Katta monument","size":"Large","desc":"Yerosti harbiy tunnel tizimi. Kuchli NPC himoyasi sababli yaxshi tayyorgarlik talab qiladi.","tips":["Kuchli qurol, o‘q-dori va davolovchi vositalar oling.","Tunnel ichida yo‘nalishni yo‘qotmaslik uchun belgilarni kuzating.","NPC bilan jangga tayyor bo‘ling."],"loot":"Harbiy konteynerlar va yuqori darajadagi loot.","color":"red","image_url":"https://images.squarespace-cdn.com/content/v1/5420d068e4b09194f76b2af6/1528945671472-76T0QN9N5V52O2LOZ9C2/image-asset.png?format=2500w","puzzle":{"cards":"Green + Blue + Red — xonaga qarab","fuses":"Puzzle yo‘liga qarab farq qiladi","route":["Kuchli qurol, ko‘p o‘q-dori va medkit olib boring.","Tunnel ichidagi NPC’larni ehtiyotkorlik bilan tozalang.","Rangli kartalar bilan tegishli eshiklarni oching.","Chuqur loot xonasiga kirishdan oldin chiqish yo‘lini belgilang."],"reward":"Elite/Military loot","note":"Tunnel ichidagi ko‘p bosqichli eshiklar sababli yagona fuse sonini ko‘rsatish noto‘g‘ri bo‘lishi mumkin."}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('The Dome', 'monument-the-dome', 'monument', 'O‘rta monument', 'Katta gumbazli sanoat inshooti. Tepaga ko‘tarilish yo‘li va atrofdagi loot nuqtalari bilan tanilgan.', '{"name":"The Dome","type":"O‘rta monument","size":"Medium","desc":"Katta gumbazli sanoat inshooti. Tepaga ko‘tarilish yo‘li va atrofdagi loot nuqtalari bilan tanilgan.","tips":["Tepaga chiqishda yiqilish xavfiga e’tibor bering.","Atrofdagi konteyner va barrelni ham tekshiring."],"loot":"Harbiy/sanoat konteynerlari.","color":"orange","image_url":"https://lone.design/wp-content/uploads/2023/11/RustClient_TwdEobhWgY-1536x864.jpg","puzzle":{"cards":"Green","fuses":"1 × Electric Fuse","route":["Dome atrofidagi fuse box va elektr switchni toping.","Electric Fuse joylang va switchni yoqing.","Green Keycard’ni reader’da swipe qiling.","Blue Keycard va blueprint fragmentini olib, xavfsiz chiqing."],"reward":"Blue Keycard va Basic Blueprint Fragment"}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Large Oil Rig', 'monument-large-oil-rig', 'monument', 'Dengiz monumenti', 'Dengizdagi yirik neft platformasi. Kuchli NPC qarshiligi va yuqori darajadagi loot mavjud.', '{"name":"Large Oil Rig","type":"Dengiz monumenti","size":"Large","desc":"Dengizdagi yirik neft platformasi. Kuchli NPC qarshiligi va yuqori darajadagi loot mavjud.","tips":["Qayiq yoki boshqa dengiz transportini rejalashtiring.","Kuchli qurol va yetarli o‘q-dori oling.","Heavy Scientist jangiga tayyor bo‘ling."],"loot":"Yuqori darajadagi harbiy loot va locked crate.","color":"red","image_url":"https://xboxplay.games/uploadStream/16905.jpg","puzzle":{"cards":"Red (xona bo‘yicha farq qiladi)","fuses":"1 × Electric Fuse (fuse xonasi)","route":["Qayiq yoki RHIB bilan platformaga yaqinlashing.","Pastki qavatlarni tozalab, yuqoriga ko‘tariling.","Fuse xonasida Electric Fuse va switchdan foydalaning.","Kerakli card reader orqali loot xonasiga kiring.","Locked Crate’ni ochishdan oldin chiqish rejasini tayyorlang."],"reward":"Elite Military Crates va Locked Crate"}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Small Oil Rig', 'monument-small-oil-rig', 'monument', 'Dengiz monumenti', 'Kichik neft platformasi. Dengizdagi loot marshruti va locked crate imkoniyati bilan mashhur.', '{"name":"Small Oil Rig","type":"Dengiz monumenti","size":"Medium","desc":"Kichik neft platformasi. Dengizdagi loot marshruti va locked crate imkoniyati bilan mashhur.","tips":["Dengiz transporti va qaytish yo‘lini oldindan belgilang.","NPC larni bittalab tozalashga harakat qiling."],"loot":"Harbiy loot va locked crate.","color":"red","image_url":"https://www.4noobs.co/api/wiki/image-proxy?url=https%3A%2F%2Fcdn.4noobs.co%2FR4N%2Fwiki%2Fsmall-oil-rig.png","puzzle":{"cards":"Blue / Red — xona bo‘yicha","fuses":"1 × Electric Fuse (fuse xonasi)","route":["Dengiz transporti bilan platformaga boring.","NPC’larni qavatma-qavat tozalang.","Fuse xonasini ishga tushiring va card reader’ni toping.","Locked Crate taymerini kuzatib, lootni oling."],"reward":"Military loot va Locked Crate"}}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Cargo Ship', 'monument-cargo-ship', 'monument', 'Dengiz monumenti', 'Xarita bo‘ylab harakatlanuvchi yirik kema monumenti.', '{"name":"Cargo Ship","type":"Dengiz monumenti","size":"Large","desc":"Xarita bo‘ylab harakatlanuvchi yirik kema monumenti.","tips":["Kemaga chiqishdan oldin qochish yo‘lini rejalashtiring.","NPC va boshqa o‘yinchilarga tayyor bo‘ling.","Locked crate vaqtini kuzating."],"loot":"Yuqori darajadagi loot va locked crate.","color":"red","image_url":"https://files.facepunch.com/s/acb148eedcae.png"}'::jsonb, 'published') on conflict (slug) do nothing;
insert into public.content_entries (title, slug, content_type, category, description, body, status) values ('Arctic Research Base', 'monument-arctic-research-base', 'monument', 'Katta monument', 'Qorli biomdagi tadqiqot bazasi. Sovuq muhit va harbiy loot imkoniyatlariga ega.', '{"name":"Arctic Research Base","type":"Katta monument","size":"Large","desc":"Qorli biomdagi tadqiqot bazasi. Sovuq muhit va harbiy loot imkoniyatlariga ega.","tips":["Sovuqdan himoyalovchi kiyim oling.","Binolar va tashqi yo‘laklarni tekshiring."],"loot":"Harbiy va ilmiy mavzudagi konteynerlar.","color":"orange","image_url":"https://luridan.com/pictures/rust-8-2022-10.jpg","puzzle":{"cards":"Blue","fuses":"Standart puzzle uchun fuse ko‘rsatilmagan","route":["Sovuqdan himoyalovchi kiyim va Blue/Red kartalar bilan tayyorlaning.","Binolar ichidagi switch va card reader yo‘nalishini kuzating.","Red Keycard bilan yopiq xonani oching.","NPC va radiatsiya xavfini nazorat qiling."],"reward":"Harbiy loot va puzzle konteynerlari"}}'::jsonb, 'published') on conflict (slug) do nothing;
